<script lang="ts">
import {Component, Prop} from 'vue-property-decorator'
import CSImage from '@/cs/view/CSImage.vue'
import CSImageGallery from '@/cs/view/CSImageGallery.vue'
import CSYoutubeVideo from '@/cs/view/CSYoutubeVideo.vue'
import PortalPageBase from '@/view/PortalPageBase'
import {ProjectData} from '@/model/Data/ProjectData'
import {ProjectRoute} from '@/model/Data/ContentRoutes'
import type {SolutionData} from '@/model/Data/SolutionsData'
import {absoluteAssetUrl, breadcrumbList, canonicalUrl, imageAltForTitle, organizationStub, pageMetaInfo, personStub, projectDescription, stripHtml} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import {isoDate, temporalCoverage} from '@/model/content/DateFormat'
import {TopBarNavigationTarget} from '@/view/View'

const operatingSystemLabels: Record<string, string> = {
  android: 'Android', ios: 'iOS', macos: 'macOS'
}

/** A schema-friendly operating-system string derived from a project's platforms. */
function operatingSystemFrom(platforms: ProjectData['platforms']): string {
  const labels = platforms.map(platform => operatingSystemLabels[platform]).filter(Boolean)
  return labels.length === 1 ? labels[0] : labels.join(', ')
}

type ParentProject = {
  project: ProjectData
  path: string
}

@Component({components: {CSImage, CSImageGallery, CSYoutubeVideo}})
export default class CaseStudyDetail extends PortalPageBase {
  @Prop({required: true}) projectRoute!: ProjectRoute

  pageTitle = this.titles.projectPage

  get project(): ProjectData | undefined {
    return this.model.projects.get(this.projectRoute)
  }

  get parent(): ParentProject | undefined {
    const project = this.model.projects.findParentByRoute(this.projectRoute)
    if (!project) return undefined
    return {project, path: this.constants.projectPath(project.route)}
  }

  get backPath() {
    return this.parent?.path || this.constants.projectsPath
  }

  get backTitle() {
    return this.parent?.project.title || this.titles.projectsPage
  }

  get topBarNavigation(): TopBarNavigationTarget {
    return {to: {path: this.backPath}, title: this.backTitle}
  }

  get hasNarrative() {
    return Boolean(
      this.project && (
        this.project.problem ||
        this.project.contribution ||
        this.project.technicalWork.length ||
        this.project.outcome
      )
    )
  }

  get subProjects() {
    if (!this.project) return []
    return this.model.projects.subProjectsOf(this.project)
  }

  get relatedSolutions(): SolutionData[] {
    if (!this.project) return []
    return this.project.solutionRoutes
      .map(route => this.model.solutions.get(route))
      .filter((solution): solution is SolutionData => Boolean(solution))
  }

  get projectImageAlts() {
    return this.project ? this.project.images.map((image, index) => this.projectImageAlt(index)) : []
  }

  get projectHeroImageAlt() {
    return this.project ? this.heroImageAlt(this.project) : this.titles.projectPage
  }

  heroImageAlt(project: ProjectData) {
    const galleryIndex = project.images.indexOf(project.heroImage)
    return galleryIndex >= 0
      ? project.imageAlts[galleryIndex] || imageAltForTitle(project.title, galleryIndex)
      : imageAltForTitle(project.title, 0)
  }

  projectImageAlt(index: number) {
    return this.project?.imageAlts[index] ||
      imageAltForTitle(this.project?.title || this.titles.projectPage, index)
  }

  get canonicalPath() {
    if (!this.project) return this.$route.path
    return this.constants.projectPath(this.project.route)
  }

  metaInfo(): any {
    const project = this.project
    if (!project) {
      return pageMetaInfo(
        this.titles.projectPage,
        this.titles.projectsDescription,
        this.$route.path,
        this.model.profile.profileImages[0]
      )
    }
    const profile = this.model.profile
    const graph: any[] = [
      {
        '@type': 'CreativeWork',
        name: stripHtml(project.title),
        description: stripHtml(project.subtitle),
        image: absoluteAssetUrl(project.heroImage),
        url: canonicalUrl(this.canonicalPath),
        datePublished: isoDate(project.startDate),
        temporalCoverage: temporalCoverage(project.periods),
        author: personStub(profile),
        about: this.relatedSolutions.map(solution => ({'@type': 'Thing', name: solution.title}))
      }
    ]

    // A published app-store listing becomes a resolvable MobileApplication. The
    // primary (base-package) link is the node; publisher is the Renetik org only
    // for Renetik-owned products, never for client-owned apps.
    const appLink = project.links.find(link => link.kind === 'app')
    if (appLink) {
      const isRenetikOwned = project.clients[0]?.id === 'renetik'
      const screenshots = Array.from(new Set([project.heroImage, ...project.images].filter(Boolean)))
        .slice(0, 6)
        .map(absoluteAssetUrl)
      const appNode: any = {
        '@type': 'MobileApplication',
        '@id': `${canonicalUrl(this.canonicalPath, 'en')}#app`,
        name: stripHtml(project.title),
        description: stripHtml(project.subtitle) || stripHtml(project.cardSummary),
        operatingSystem: operatingSystemFrom(project.platforms),
        applicationCategory: 'MultimediaApplication',
        installUrl: appLink.url,
        sameAs: [appLink.url],
        author: personStub(profile),
        screenshot: screenshots
      }
      if (isRenetikOwned) {
        appNode.applicationSubCategory = 'Music production'
        appNode.publisher = organizationStub()
      }
      graph.push(appNode)
    }

    // A grouping case study enumerates its app children as one machine-readable
    // list — the ten Android music apps resolve in one place on the parent page.
    const childAppItems = this.subProjects
      .filter(child => child.links.some(link => link.kind === 'app'))
      .map((child, index) => ({
        '@type': 'ListItem',
        position: index + 1,
        url: `${canonicalUrl(this.constants.projectPath(child.route), 'en')}#app`,
        name: stripHtml(child.title)
      }))
    if (childAppItems.length) {
      graph.push({'@type': 'ItemList', name: stripHtml(project.title), itemListElement: childAppItems})
    }

    graph.push(breadcrumbList([
      {name: brandName, path: '/'},
      {name: this.titles.homePage, path: this.constants.introductionPath},
      {name: this.titles.projectsPage, path: this.constants.projectsPath},
      {name: stripHtml(project.title), path: this.canonicalPath}
    ]))

    const structuredData = {'@context': 'https://schema.org', '@graph': graph}
    return pageMetaInfo(
      stripHtml(project.title),
      projectDescription(project),
      this.canonicalPath,
      project.heroImage,
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
